1	type Customer = { yearsWithMHPCO: number };
2	type Item = { type: string; material?: string; enchantment?: number; cursed?: boolean };
3	type Damage = { itemType: string; amount: number };
4	type Incident = { cause: string; damages: Damage[] };
5	type QuoteStep = { op: "quote"; items: Item[] };
6	type ClaimStep = { op: "claim"; policy: number; incident: Incident };
7	type Step = QuoteStep | ClaimStep;
8	type Scenario = { customer: Customer; steps: Step[] };
9	
10	type QuoteResult = { premium: number };
11	type ClaimResult = { payout: number; remainingCap: number };
12	type StepResult = QuoteResult | ClaimResult;
13	type ScenarioResult = { results: StepResult[] };
14	
15	const PROCESSING_FEE = 5;
16	const FIRST_INSURANCE_PCT = 0.10;
17	const LOYALTY_PCT = 0.20;
18	const LOYALTY_YEARS = 2;
19	const FOLLOW_UP_PCT = 0.15;
20	const CURSE_PCT = 0.50;
21	const HIGH_ENCH_PCT = 0.30;
22	const HIGH_ENCH_THRESHOLD = 5;
23	const FLOAT_TOLERANCE = 1e-9;
24	const BLOCK_SIZE = 3;
25	const BLOCK_PREMIUM = 60;
26	const DEDUCTIBLE = 100;
27	const CAP_MULTIPLIER = 2;
28	const HIGH_ENCH_PAYOUT_FACTOR = 0.5;
29	const HIGH_ENCH_PAYOUT_THRESHOLD = 8;
30	const DRAGON_MATERIAL = "dragon";
31	
32	const BASE_PREMIUM: Record<string, number> = {
33	  sword: 100,
34	  amulet: 60,
35	  staff: 80,
36	  potion: 40,
37	  rune: 25,
38	  moonstone: 25,
39	};
40	
41	const INSURANCE_VALUE: Record<string, number> = {
42	  sword: 1000,
43	  amulet: 600,
44	  staff: 800,
45	  potion: 400,
46	  rune: 250,
47	  moonstone: 250,
48	};
49	
50	const COMPONENT_TYPES = new Set(["rune", "moonstone"]);
51	
52	const isComponentType = (type: string): boolean => COMPONENT_TYPES.has(type);
53	
54	const roundUp = (n: number): number => Math.ceil(n - FLOAT_TOLERANCE);
55	const roundDown = (n: number): number => Math.floor(n + FLOAT_TOLERANCE);
56	
57	const countByType = (items: Item[]): Map<string, number> => {
58	  const counts = new Map<string, number>();
59	  for (const item of items) {
60	    counts.set(item.type, (counts.get(item.type) ?? 0) + 1);
61	  }
62	  return counts;
63	};
64	
65	const groupBasePremium = (type: string, count: number): number =>
66	  isComponentType(type) && count === BLOCK_SIZE
67	    ? BLOCK_PREMIUM
68	    : count * BASE_PREMIUM[type];
69	
70	const sumBasePremiums = (items: Item[]): number => {
71	  let total = 0;
72	  for (const [type, count] of countByType(items)) {
73	    total += groupBasePremium(type, count);
74	  }
75	  return total;
76	};
77	
78	const isHighlyEnchanted = (item: Item): boolean =>
79	  (item.enchantment ?? 0) >= HIGH_ENCH_THRESHOLD;
80	
81	const itemSurchargePct = (item: Item): number =>
82	  (item.cursed ? CURSE_PCT : 0) +
83	  (isHighlyEnchanted(item) ? HIGH_ENCH_PCT : 0);
84	
85	const itemSurcharge = (item: Item): number =>
86	  BASE_PREMIUM[item.type] * itemSurchargePct(item);
87	
88	const itemSurcharges = (items: Item[]): number =>
89	  items.reduce((total, item) => total + itemSurcharge(item), 0);
90	
91	const loyaltyDiscountPct = (customer: Customer): number =>
92	  customer.yearsWithMHPCO >= LOYALTY_YEARS ? LOYALTY_PCT : 0;
93	
94	const followUpDiscountPct = (priorQuoteCount: number): number =>
95	  priorQuoteCount > 0 ? FOLLOW_UP_PCT : 0;
96	
97	const policyBaseMultiplier = (customer: Customer, priorQuoteCount: number): number =>
98	  1 + FIRST_INSURANCE_PCT - loyaltyDiscountPct(customer) - followUpDiscountPct(priorQuoteCount);
99	
100	const computeQuotePremium = (items: Item[], customer: Customer, priorQuoteCount: number): number => {
101	  const policyBase = sumBasePremiums(items);
102	  return roundUp(
103	    policyBase * policyBaseMultiplier(customer, priorQuoteCount) + itemSurcharges(items) + PROCESSING_FEE,
104	  );
105	};
106	
107	type Policy = { items: Item[]; insuranceSum: number; remainingCap: number };
108	
109	const insuranceSumOf = (items: Item[]): number =>
110	  items.reduce((sum, item) => sum + INSURANCE_VALUE[item.type], 0);
111	
112	const makePolicy = (items: Item[]): Policy => {
113	  const insuranceSum = insuranceSumOf(items);
114	  return { items, insuranceSum, remainingCap: insuranceSum * CAP_MULTIPLIER };
115	};
116	
117	const findMatchingItem = (items: Item[], damage: Damage, consumed: Set<number>): number => {
118	  for (let i = 0; i < items.length; i++) {
119	    if (!consumed.has(i) && items[i].type === damage.itemType) return i;
120	  }
121	  return -1;
122	};
123	
124	const rawPayoutForItem = (item: Item, damageAmount: number): number => {
125	  if (item.material === DRAGON_MATERIAL) return damageAmount;
126	  if ((item.enchantment ?? 0) >= HIGH_ENCH_PAYOUT_THRESHOLD) return damageAmount * HIGH_ENCH_PAYOUT_FACTOR;
127	  return damageAmount;
128	};
129	
130	const processClaim = (policy: Policy, incident: Incident): ClaimResult => {
131	  let totalPayout = 0;
132	  const consumed = new Set<number>();
133	  for (const damage of incident.damages) {
134	    if (damage.amount < 0) throw new Error(`negative damage amount: ${damage.amount}`);
135	    const idx = findMatchingItem(policy.items, damage, consumed);
136	    if (idx === -1) throw new Error(`damage references item not in policy: ${damage.itemType}`);
137	    consumed.add(idx);
138	    const raw = rawPayoutForItem(policy.items[idx], damage.amount);
139	    const afterDeductible = Math.max(0, raw - DEDUCTIBLE);
140	    const paid = Math.min(afterDeductible, policy.remainingCap - totalPayout);
141	    totalPayout += paid;
142	  }
143	  policy.remainingCap -= totalPayout;
144	  return { payout: roundDown(totalPayout), remainingCap: policy.remainingCap };
145	};
146	
147	const validateItems = (items: Item[]): void => {
148	  for (const item of items) {
149	    if (!(item.type in BASE_PREMIUM)) {
150	      throw new Error(`unknown item type: ${item.type}`);
151	    }
152	  }
153	};
154	
155	export const runScenario = (scenario: Scenario): ScenarioResult => {
156	  const results: StepResult[] = [];
157	  const policies: Policy[] = [];
158	  let priorQuoteCount = 0;
159	  for (const step of scenario.steps) {
160	    if (step.op === "quote") {
161	      validateItems(step.items);
162	      results.push({ premium: computeQuotePremium(step.items, scenario.customer, priorQuoteCount) });
163	      policies.push(makePolicy(step.items));
164	      priorQuoteCount++;
165	    } else {
166	      const policy = policies[step.policy];
167	      results.push(processClaim(policy, step.incident));
168	    }
169	  }
170	  return { results };
171	};
